<?php

namespace Ediligence\EdiligenceBundle\Repository;
Use Doctrine\ORM\Query\Expr\Join;
/**
 * TarchiveRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class TarchiveRepository extends \Doctrine\ORM\EntityRepository
{  
    public function archive(){
       $qb = $this->createQueryBuilder('a')
                  ->addSelect("(case when sc.code_sc Is Not Null then sc.abrv else case when sd.code_sd Is Not Null then sd.abrv else case when dc.code_dc Is Not Null then dc.sigle else case when dg.codeDg Is Not Null then dg.abrv else case when x.matricule Is Not Null Then Concat(x.nom, ' ', x.prenoms, ' ', x.nomJeuneFille) else 1 end end end end end) as service, "
                          . "i.dateImput, c.reforigine, c.objet, t.datetraitement, t.idImput")
                  ->innerJoin('EdiligenceBundle:Tcourrier', 'c',  Join::WITH,'a.codecourrier = c.id')
                  ->innerJoin('EdiligenceBundle:Ttraitement', 't',  Join::WITH,'a.traitements = t.id And a.codecourrier = t.codecourrier')
                  ->innerJoin('EdiligenceBundle:Timputations', 'i',  Join::WITH,'t.idImput = i.id')
                  ->leftJoin('AgentBundle:DirectionGenerale', 'dg',  Join::WITH,'i.coordinateur = dg.codeDg')
                  ->leftJoin('AgentBundle:Direction', 'dc',  Join::WITH,'i.coordinateur = dc.code_dc')
                  ->leftJoin('AgentBundle:SousDirection', 'sd',  Join::WITH,'i.coordinateur = sd.code_sd')
                  ->leftJoin('AgentBundle:ServiceDirection', 'sc',  Join::WITH,'i.coordinateur = sc.code_sc')
                  ->leftJoin('AgentBundle:Agent', 'x',  Join::WITH,'i.coordinateur = x.matricule')
                  ->where('c.etataff = :etataff')
                  ->setParameter("etataff", 1)
                  ->orderBy('a.id', 'DESC');
       
       return $qb->getQuery()->getResult();  
    }
    
}
